class CpGradient {
  CpGradient._();
  static const LinearGradient brand = LinearGradient(begin: Alignment(-1, 0), end: Alignment(1, 0), colors: [Color(0xFF381987), Color(0xFF01AAA5)], stops: [0, 1]);
  static const LinearGradient spark = LinearGradient(begin: Alignment(-1, 0), end: Alignment(1, 0), colors: [Color(0xFFFDA73B), Color(0xFFF65F4F)], stops: [0, 1]);

  /// The product's logo gradient (left -> right).
  static LinearGradient product(CpProduct product) {
    switch (product) {
      case CpProduct.consumer:
        return const LinearGradient(colors: [Color(0xFF381987), Color(0xFF01AAA5)]);
      case CpProduct.seller:
        return const LinearGradient(colors: [Color(0xFFF65F4F), Color(0xFFFDA73B)]);
      case CpProduct.delivery:
        return const LinearGradient(colors: [Color(0xFF750C6F), Color(0xFFED0066)]);
      case CpProduct.console:
        return const LinearGradient(colors: [Color(0xFF3C2566), Color(0xFF9478CB)]);
      case CpProduct.events:
        return const LinearGradient(colors: [Color(0xFF5F3A9F), Color(0xFF3966E6)]);
      case CpProduct.kampus:
        return const LinearGradient(colors: [Color(0xFF2450CC), Color(0xFF38BDF8)]);
      case CpProduct.menu:
        return const LinearGradient(colors: [Color(0xFFE1517D), Color(0xFFED7325)]);
    }
  }
}

