  static const Duration slow = Duration(milliseconds: 450);
  static const Duration deliberate = Duration(milliseconds: 600);
  static const Duration shimmer = Duration(milliseconds: 1400);
  static const Cubic standardCurve = Cubic(0.2, 0, 0, 1);
  static const Cubic enterCurve = Cubic(0, 0, 0, 1);
  static const Cubic exitCurve = Cubic(0.3, 0, 1, 1);
  static const Cubic emphasizedCurve = Cubic(0.3, 0, 0, 1);
  static const Cubic linearCurve = Cubic(0, 0, 1, 1);
  static const double pressedScale = 0.97;
  static const double disabledOpacity = 0.4;

  /// Honour the OS 'reduce motion' setting.
  static Duration adaptive(BuildContext context, Duration d) =>
      MediaQuery.maybeOf(context)?.disableAnimations == true ? (d > fast ? fast : d) : d;
}

/// Builds a Material 3 ThemeData for a ChangePay product.
///   MaterialApp(theme: CpTheme.build(CpProduct.seller), darkTheme: CpTheme.build(CpProduct.seller, Brightness.dark))
/// Read brand colors anywhere with `Theme.of(context).extension<CpColors>()!`.
class CpTheme {
  CpTheme._();

  static ThemeData build(CpProduct product, [Brightness brightness = Brightness.light]) {
    final c = CpColors.of(product, brightness);
    final scheme = ColorScheme(
      brightness: brightness,
      primary: c.primary,
      onPrimary: c.onPrimary,
      primaryContainer: c.primarySubtle,
      onPrimaryContainer: c.onPrimarySubtle,
      secondary: c.accent,
      onSecondary: c.onAccent,
      error: c.danger,
      onError: c.onPrimary,
      errorContainer: c.dangerSubtle,
      onErrorContainer: c.onDangerSubtle,
      surface: c.surface,
      onSurface: c.text,
      onSurfaceVariant: c.textMuted,
      outline: c.borderStrong,
      outlineVariant: c.border,
      scrim: c.scrim,
      shadow: CpPalette.ink950,
      inverseSurface: c.text,
      onInverseSurface: c.surface,
      inversePrimary: c.primarySubtle,
      surfaceTint: Colors.transparent,
    );
    TextStyle t(TextStyle s, Color col) => s.copyWith(color: col);
    final text = TextTheme(
      displayLarge: t(CpType.displayLg, c.text),
      displayMedium: t(CpType.display, c.text),
      headlineLarge: t(CpType.h1, c.text),
      headlineMedium: t(CpType.h2, c.text),
      headlineSmall: t(CpType.h3, c.text),
      titleLarge: t(CpType.h3, c.text),
      titleMedium: t(CpType.title, c.text),
      titleSmall: t(CpType.bodyStrong, c.text),
      bodyLarge: t(CpType.bodyLg, c.text),
      bodyMedium: t(CpType.body, c.text),
      bodySmall: t(CpType.caption, c.textMuted),
      labelLarge: t(CpType.label, c.text),
      labelMedium: t(CpType.labelSm, c.text),
      labelSmall: t(CpType.overline, c.textMuted),
    );
    final shape = RoundedRectangleBorder(borderRadius: BorderRadius.circular(CpRadius.md));
    final buttonSize = WidgetStateProperty.all(const Size(64, CpSize.button));
    return ThemeData(
      useMaterial3: true,
      colorScheme: scheme,
      scaffoldBackgroundColor: c.bg,
      textTheme: text,
      fontFamily: CpFonts.text,
      dividerColor: c.divider,
      splashFactory: InkSparkle.splashFactory,
      extensions: <ThemeExtension<dynamic>>[c],
      appBarTheme: AppBarTheme(backgroundColor: c.surface, foregroundColor: c.text, elevation: 0,
          scrolledUnderElevation: 0, centerTitle: false, titleTextStyle: t(CpType.title, c.text)),
      filledButtonTheme: FilledButtonThemeData(style: ButtonStyle(minimumSize: buttonSize,
          shape: WidgetStateProperty.all(shape), textStyle: WidgetStateProperty.all(CpType.label))),
      outlinedButtonTheme: OutlinedButtonThemeData(style: ButtonStyle(minimumSize: buttonSize,
          shape: WidgetStateProperty.all(shape), textStyle: WidgetStateProperty.all(CpType.label),
          side: WidgetStateProperty.all(BorderSide(color: c.borderStrong)))),
      textButtonTheme: TextButtonThemeData(style: ButtonStyle(textStyle: WidgetStateProperty.all(CpType.label))),
      cardTheme: CardThemeData(color: c.surface, elevation: 0, margin: EdgeInsets.zero,
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(CpRadius.lg), side: BorderSide(color: c.border))),
      inputDecorationTheme: InputDecorationTheme(
        filled: true,
        fillColor: c.surface,
        contentPadding: const EdgeInsets.symmetric(horizontal: CpSpace.s4, vertical: CpSpace.s3),
        border: OutlineInputBorder(borderRadius: BorderRadius.circular(CpRadius.md), borderSide: BorderSide(color: c.borderStrong)),
        enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(CpRadius.md), borderSide: BorderSide(color: c.borderStrong)),
        focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(CpRadius.md), borderSide: BorderSide(color: c.primary, width: 2)),
        errorBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(CpRadius.md), borderSide: BorderSide(color: c.danger)),
        hintStyle: t(CpType.bodyLg, c.textSubtle),
      ),
      bottomSheetTheme: BottomSheetThemeData(backgroundColor: c.surface, showDragHandle: true,
          shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(CpRadius.xl)))),
      dialogTheme: DialogThemeData(backgroundColor: c.surface,
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(CpRadius.xl))),
      snackBarTheme: SnackBarThemeData(behavior: SnackBarBehavior.floating, backgroundColor: c.text,
          contentTextStyle: t(CpType.body, c.surface), shape: shape),
      chipTheme: ChipThemeData(shape: const StadiumBorder(), labelStyle: t(CpType.labelSm, c.text), side: BorderSide(color: c.border)),
      navigationBarTheme: NavigationBarThemeData(height: CpSize.tabBar, backgroundColor: c.surface,
          indicatorColor: c.primarySubtle, labelTextStyle: WidgetStateProperty.all(t(CpType.caption, c.text))),
      pageTransitionsTheme: const PageTransitionsTheme(builders: {
        TargetPlatform.android: FadeForwardsPageTransitionsBuilder(),
      }),
    );
  }
}
